// CRDT compaction and snapshot reads bound the storage a long-lived document
// accumulates in the CRDT state layer. Merges only ever need a small part of
// the accepted history: a counter merges from each device's maximum
// contribution, a gset from the element union, a register from each device's
// latest version and the winner among them, and an orset from its live tags
// and the tombstones covering dead ones. Everything else no longer affects
// the merged result and can be trimmed.
//
// Compaction rewrites nothing outside the CRDT tables: it never allocates a
// change cursor, never writes a change record and never notifies subscribers,
// because the merged value does not move. The trimmed state still reproduces
// the exact merge and still answers the submission layer's questions. A
// snapshot read reports the merged value together with the number of stored
// operations and tombstones; both counts are non-negative and durable across
// restarts. The identity table is neither count.

package crdt

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// Compact trims every stored operation and tombstone that no longer affects
// the document's merged result, in one serialized transaction, and returns the
// post-compaction snapshot (byte-for-byte what a snapshot read returns
// immediately afterward).
//
// The gate is enforced exactly as in SubmitOps and before any CRDT content is
// observed: an unregistered device yields store.ErrDeviceNotFound and a
// revoked device yields store.ErrPermissionDenied, and neither touches any
// state. A document with no committed CRDT operation yields ErrNotFound. Any
// failure leaves the state untouched.
//
// Per type, compaction keeps precisely the rows the merge and the submission
// checks still read:
//
//   - counter: each device's maximum contribution (ties keep the
//     lexicographically smaller operation id). The per-device maxima table is
//     untouched. Each dropped id keeps a device-plus-value identity.
//   - gset: a minimal prefix cover of the union, operations considered in
//     ascending id order. The union table is untouched. Each dropped id keeps
//     a device-plus-elements identity.
//   - register: each device's greatest-version operation. Each dropped older
//     id keeps a device-plus-version-plus-value identity.
//   - orset: live add tags; tombstoned tags are dropped together with the
//     tombstones covering them. The operation log is untouched, so replaying
//     either one stays idempotent; no identity row is needed.
//
// Compaction is idempotent: a second run finds nothing to trim and returns
// the same snapshot. It commits no change-log row, allocates no cursor and,
// because the merged value never moves, notifies no subscriber.
func (s *Service) Compact(documentID, deviceID string) (Snapshot, error) {
	// Serialize with submissions and other compactions: the trim and the
	// submission checks read the same rows, so they must not interleave.
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return Snapshot{}, err
	}
	defer func() { _ = tx.Rollback() }()

	// Registration and permission are enforced before any CRDT content is
	// observed, so a rejected compaction cannot reveal type or state.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return Snapshot{}, err
		}
	}

	var docType string
	err = tx.QueryRow(
		`SELECT type FROM crdt_documents WHERE document_id = ?`, documentID,
	).Scan(&docType)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return Snapshot{}, ErrNotFound
	case err != nil:
		return Snapshot{}, err
	}

	switch docType {
	case TypeCounter:
		if err := compactCounterOps(tx, documentID); err != nil {
			return Snapshot{}, err
		}
	case TypeGSet:
		if err := compactGSetOps(tx, documentID); err != nil {
			return Snapshot{}, err
		}
	case TypeRegister:
		if err := compactRegisterOps(tx, documentID); err != nil {
			return Snapshot{}, err
		}
	case TypeORSet:
		if err := compactORSetOps(tx, documentID); err != nil {
			return Snapshot{}, err
		}
	}

	if err := tx.Commit(); err != nil {
		return Snapshot{}, err
	}
	// The commit is durable and the submission mutex is still held, so no
	// submission or compaction can interleave before this read.
	return s.GetSnapshot(documentID)
}

// compactCounterOps drops every counter operation superseded by a greater
// contribution from the same device, keeping exactly one operation per
// device: its maximum contribution, ties broken by the smaller operation id.
// Before a row is dropped its identity is retained.
func compactCounterOps(tx *sql.Tx, documentID string) error {
	rows, err := tx.Query(
		`SELECT id, device_id, value FROM crdt_ops WHERE document_id = ? ORDER BY id ASC`,
		documentID,
	)
	if err != nil {
		return err
	}
	type contribution struct {
		id    string
		value int64
		raw   []byte
	}
	best := make(map[string]contribution)
	var drop []Op
	for rows.Next() {
		var id, deviceID string
		var raw []byte
		if err := rows.Scan(&id, &deviceID, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		value, err := decodeCounterValue(raw)
		if err != nil {
			_ = rows.Close()
			return err
		}
		// Ids arrive in ascending order, so the first contribution seen at the
		// device's maximum value carries the smallest id.
		if cur, ok := best[deviceID]; !ok || value > cur.value {
			if ok {
				drop = append(drop, Op{ID: cur.id, DeviceID: deviceID, Value: json.RawMessage(cur.raw)})
			}
			best[deviceID] = contribution{id: id, value: value, raw: raw}
		} else {
			drop = append(drop, Op{ID: id, DeviceID: deviceID, Value: json.RawMessage(raw)})
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()

	for _, op := range drop {
		if err := retainIdentity(tx, documentID, TypeCounter, op); err != nil {
			return err
		}
		if _, err := tx.Exec(
			`DELETE FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		); err != nil {
			return err
		}
	}
	return nil
}

// compactGSetOps drops every gset operation whose elements are all covered by
// kept operations: operations are considered in ascending id order and one is
// kept only when it contributes an element no previously kept operation
// covers. A dropped operation's identity is retained before its row is
// deleted.
func compactGSetOps(tx *sql.Tx, documentID string) error {
	rows, err := tx.Query(
		`SELECT id, device_id, value FROM crdt_ops WHERE document_id = ? ORDER BY id ASC`,
		documentID,
	)
	if err != nil {
		return err
	}
	covered := make(map[string]struct{})
	var drop []Op
	for rows.Next() {
		var id, deviceID string
		var raw []byte
		if err := rows.Scan(&id, &deviceID, &raw); err != nil {
			_ = rows.Close()
			return err
		}
		var elements []string
		if err := json.Unmarshal(raw, &elements); err != nil {
			_ = rows.Close()
			return err
		}
		keeps := false
		for _, element := range elements {
			if _, ok := covered[element]; !ok {
				keeps = true
				covered[element] = struct{}{}
			}
		}
		if !keeps {
			drop = append(drop, Op{ID: id, DeviceID: deviceID, Elements: elements})
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()

	for _, op := range drop {
		if err := retainIdentity(tx, documentID, TypeGSet, op); err != nil {
			return err
		}
		if _, err := tx.Exec(
			`DELETE FROM crdt_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		); err != nil {
			return err
		}
	}
	return nil
}

// compactRegisterOps drops every register operation superseded by a greater
// version from the same device, keeping each device's greatest-version
// operation. A dropped operation's identity is retained before its row is
// deleted.
func compactRegisterOps(tx *sql.Tx, documentID string) error {
	rows, err := tx.Query(
		`SELECT id, device_id, version, value FROM crdt_register_ops
		 WHERE document_id = ?
		   AND EXISTS (
			SELECT 1 FROM crdt_register_ops newer
			WHERE newer.document_id = crdt_register_ops.document_id
			  AND newer.device_id = crdt_register_ops.device_id
			  AND newer.version > crdt_register_ops.version
		   )`,
		documentID,
	)
	if err != nil {
		return err
	}
	var drop []Op
	for rows.Next() {
		var op Op
		if err := rows.Scan(&op.ID, &op.DeviceID, &op.Version, &op.Value); err != nil {
			_ = rows.Close()
			return err
		}
		drop = append(drop, op)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()

	for _, op := range drop {
		if err := retainIdentity(tx, documentID, TypeRegister, op); err != nil {
			return err
		}
		if _, err := tx.Exec(
			`DELETE FROM crdt_register_ops WHERE document_id = ? AND id = ?`,
			documentID, op.ID,
		); err != nil {
			return err
		}
	}
	return nil
}

// compactORSetOps drops every tombstoned add tag together with every
// tombstone: a dead tag and the tombstone covering it cancel out of the
// merge, so the live element set is unchanged. The operation log is
// untouched.
func compactORSetOps(tx *sql.Tx, documentID string) error {
	if _, err := tx.Exec(
		`DELETE FROM crdt_orset_tags
		 WHERE document_id = ?
		   AND EXISTS (
			SELECT 1 FROM crdt_orset_tombstones x
			WHERE x.document_id = crdt_orset_tags.document_id
			  AND x.element = crdt_orset_tags.element
			  AND x.op_id = crdt_orset_tags.op_id
		   )`,
		documentID,
	); err != nil {
		return err
	}
	_, err := tx.Exec(
		`DELETE FROM crdt_orset_tombstones WHERE document_id = ?`,
		documentID,
	)
	return err
}

// GetSnapshot returns the document's merged CRDT state together with the
// number of stored operations and tombstones the merge is derived from. A
// document with no committed operations yields ErrNotFound. The read is pure:
// it advances no cursor, writes nothing and registers no subscription.
func (s *Service) GetSnapshot(documentID string) (Snapshot, error) {
	state, err := s.GetState(documentID)
	if err != nil {
		return Snapshot{}, err
	}
	snapshot := Snapshot{Type: state.Type, Value: state.Value}

	count := func(query string) (int64, error) {
		var n int64
		if err := s.db.QueryRow(query, documentID).Scan(&n); err != nil {
			return 0, err
		}
		return n, nil
	}

	switch state.Type {
	case TypeCounter, TypeGSet:
		operations, err := count(`SELECT COUNT(*) FROM crdt_ops WHERE document_id = ?`)
		if err != nil {
			return Snapshot{}, err
		}
		snapshot.Operations = operations
	case TypeRegister:
		operations, err := count(`SELECT COUNT(*) FROM crdt_register_ops WHERE document_id = ?`)
		if err != nil {
			return Snapshot{}, err
		}
		snapshot.Operations = operations
	case TypeORSet:
		operations, err := count(`SELECT COUNT(*) FROM crdt_orset_tags WHERE document_id = ?`)
		if err != nil {
			return Snapshot{}, err
		}
		tombstones, err := count(`SELECT COUNT(*) FROM crdt_orset_tombstones WHERE document_id = ?`)
		if err != nil {
			return Snapshot{}, err
		}
		snapshot.Operations = operations
		snapshot.Tombstones = tombstones
	}
	return snapshot, nil
}

// Package app is the composition root: it opens the one shared database and
// constructs the three independently reusable internal services — the change
// event service, the permission service and the CRDT state service — wiring
// them together only through their internal interfaces.
//
// The services share one SQLite connection (the kernel opens a single
// pooled connection with immediate transactions), so a change commit, a CRDT
// submission or compaction, and a permission change are serialized on the
// same connection and leave no half-written batch. The change event and CRDT
// services take their registration-and-authorization verdict from the
// permission service inside their own transactions (events.Gate / crdt.Gate),
// and the permission service fans a committed revoke out to their
// subscription registries through authz.RevokeSink. No service reaches into
// another service's tables or fields.
//
// App is the single object the entry and HTTP layers use. It promotes each
// service's input/output boundary as its methods while hiding the wiring; it
// adds no authentication and exposes no endpoint of its own.
package app

import (
	"context"
	"encoding/json"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/authz"
	"github.com/alicegogogogogo/local-first-sync-service/internal/crdt"
	"github.com/alicegogogogogo/local-first-sync-service/internal/events"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// App composes the durable kernel and the three internal services over one
// shared database connection.
type App struct {
	*store.Store

	events *events.Service
	crdt   *crdt.Service

	// Authz is the permission service. It is exposed so the HTTP layer can
	// grant/revoke and read authorization directly; the other services reach
	// it through their gates rather than this field.
	Authz *authz.Service
}

// Open opens (creating if needed) the SQLite database at path and constructs
// every internal service over it. The empty path opens a private in-memory
// database useful for tests. A construction failure closes the kernel and
// leaves nothing behind.
func Open(path string) (*App, error) {
	kernel, err := store.Open(path)
	if err != nil {
		return nil, err
	}

	// The permission service is built first: its gate is a constructor
	// dependency of the change event and CRDT services.
	permissions, err := authz.New(kernel)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	eventService, err := events.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}
	crdtService, err := crdt.New(kernel, permissions)
	if err != nil {
		_ = kernel.Close()
		return nil, err
	}

	// A committed revoke ends the affected live subscriptions in both
	// push channels. The dependency is an interface, registered once here, so
	// the permission service never names either subscriber concretely.
	permissions.AddRevokeSink(eventsRevokeSink{eventService})
	permissions.AddRevokeSink(crdtService)

	return &App{
		Store:  kernel,
		events: eventService,
		crdt:   crdtService,
		Authz:  permissions,
	}, nil
}

// eventsRevokeSink adapts the change event service's revoke hook to the
// permission service's RevokeSink interface.
type eventsRevokeSink struct{ e *events.Service }

func (s eventsRevokeSink) PermissionRevoked(documentID, deviceID string) {
	s.e.SignalRevoked(documentID, deviceID)
}

// Events returns the change event service.
func (a *App) Events() *events.Service { return a.events }

// CRDT returns the CRDT state service.
func (a *App) CRDT() *crdt.Service { return a.crdt }

// ---- Change event service boundary (promoted so the entry layer has one
// object; each method delegates verbatim to the events service). ----

// InterruptWaits wakes every parked long poll and every live change-log and
// CRDT subscription without closing the database, so an orderly shutdown
// drains waiting connections (long polls answer 503; subscriptions finish
// with the going-away close) instead of holding the drain hostage.
func (a *App) InterruptWaits() {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
}

// Closing reports whether shutdown has begun, covering both push channels.
func (a *App) Closing() bool {
	return a.events.Closing() || a.crdt.Closing()
}

// Close interrupts the in-memory observers, waits for every subscription
// handler to unregister and then releases the shared database handle.
func (a *App) Close() error {
	a.events.InterruptWaits()
	a.crdt.InterruptWaits()
	a.events.WaitDrained()
	a.crdt.WaitDrained()
	return a.Store.Close()
}

// PostChanges delegates to the change event service.
func (a *App) PostChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.PostChanges(documentID, changes)
}

// ReplayChanges delegates to the change event service.
func (a *App) ReplayChanges(documentID string, changes []events.Change) ([]events.Result, error) {
	return a.events.ReplayChanges(documentID, changes)
}

// MergeChange delegates to the change event service.
func (a *App) MergeChange(documentID string, baseCursor int64, c events.Change) (events.MergeResult, error) {
	return a.events.MergeChange(documentID, baseCursor, c)
}

// PutSnapshot delegates to the change event service.
func (a *App) PutSnapshot(documentID string, cursor int64, state json.RawMessage) (bool, error) {
	return a.events.PutSnapshot(documentID, cursor, state)
}

// GetSnapshot delegates to the change event service.
func (a *App) GetSnapshot(documentID string, cursor int64) (json.RawMessage, error) {
	return a.events.GetSnapshot(documentID, cursor)
}

// ExportSnapshots delegates to the change event service. A nil to means the
// interval has no upper bound.
func (a *App) ExportSnapshots(documentID string, from int64, to *int64) ([]events.ExportedSnapshot, error) {
	return a.events.ExportSnapshots(documentID, from, to)
}

// RestoreSnapshot delegates to the change event service.
func (a *App) RestoreSnapshot(documentID, deviceID, changeID string, snapshotCursor int64) (events.RestoreResult, error) {
	return a.events.RestoreSnapshot(documentID, deviceID, changeID, snapshotCursor)
}

// ListChanges delegates to the change event service.
func (a *App) ListChanges(documentID string, after, limit int64) ([]events.ListedChange, int64, error) {
	return a.events.ListChanges(documentID, after, limit)
}

// WaitForChanges delegates to the change event service.
func (a *App) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) ([]events.ListedChange, int64, bool, error) {
	return a.events.WaitForChanges(ctx, documentID, after, limit, wait)
}

// DocumentExists delegates to the change event service.
func (a *App) DocumentExists(documentID string) (bool, error) {
	return a.events.DocumentExists(documentID)
}

// AddSubscription delegates to the change event service.
func (a *App) AddSubscription(documentID, deviceID string) (<-chan struct{}, <-chan struct{}, func()) {
	return a.events.AddSubscription(documentID, deviceID)
}

// DeregisterDevice removes a registered device together with every record it
// owns — its sessions, the attachments it created (chunks, sealed state and
// unfinished uploads included), the access grants it held, and its
// document-permission rows — all in one serialized transaction that commits
// synchronously. An unknown or already deregistered device yields
// store.ErrDeviceNotFound and writes nothing, so a repeat deregistration
// misses exactly the way a never-registered id does and concurrent calls take
// effect at most once. Shared digest-addressed content is reclaimed only when
// the last completed attachment referencing it is gone; other devices'
// changes, snapshots and document content are untouched.
//
// After the commit the same id may register again as a brand-new device — no
// session, permission or attachment is inherited — and every live
// subscription the device held across both push channels is ended
// immediately, stickily.
func (a *App) DeregisterDevice(deviceID string) error {
	tx, err := a.Store.DB().Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	if err := store.DeleteDeviceTx(tx, deviceID); err != nil {
		return err
	}
	if err := a.Authz.DeleteDevicePermissionsTx(tx, deviceID); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return err
	}

	// End the device's live subscriptions only after the cascade is durable:
	// a reconnect attempt after the close finds the backing session gone
	// (404), so the connection cannot immediately re-establish itself.
	a.events.SignalDeviceDeregistered(deviceID)
	a.crdt.SignalDeviceDeregistered(deviceID)
	return nil
}

// ---- Permission service boundary. ----

// SetDocumentPermission delegates to the permission service.
func (a *App) SetDocumentPermission(documentID, deviceID string, authorized bool) (bool, error) {
	return a.Authz.SetDocumentPermission(documentID, deviceID, authorized)
}

// DocumentAuthorized delegates to the permission service.
func (a *App) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	return a.Authz.DocumentAuthorized(documentID, deviceID)
}

// ---- CRDT state service boundary. ----

// SubmitCRDTOps delegates to the CRDT state service.
func (a *App) SubmitCRDTOps(documentID, declaredType string, ops []crdt.Op) ([]crdt.Result, error) {
	return a.crdt.SubmitOps(documentID, declaredType, ops)
}

// GetCRDTState delegates to the CRDT state service.
func (a *App) GetCRDTState(documentID string) (crdt.State, error) {
	return a.crdt.GetState(documentID)
}

// CompactCRDT delegates to the CRDT state service.
func (a *App) CompactCRDT(documentID, deviceID string) (crdt.Snapshot, error) {
	return a.crdt.Compact(documentID, deviceID)
}

// GetCRDTSnapshot delegates to the CRDT state service.
func (a *App) GetCRDTSnapshot(documentID string) (crdt.Snapshot, error) {
	return a.crdt.GetSnapshot(documentID)
}

// OpenCRDTSubscription delegates to the CRDT state service.
func (a *App) OpenCRDTSubscription(documentID, deviceID string) (*crdt.State, *crdt.Subscription, func(), error) {
	return a.crdt.OpenSubscription(documentID, deviceID)
}

// AddCRDTSubscription delegates to the CRDT state service.
func (a *App) AddCRDTSubscription(documentID, deviceID string) (*crdt.Subscription, func()) {
	return a.crdt.AddSubscription(documentID, deviceID)
}

// Accepted-operation identities keep idempotency and conflict decisions
// working after compaction. Compaction trims the rows a merge derives its
// result from, but a re-submitted operation id must still be recognized. When
// a row is trimmed, compaction moves the only information that decision
// compares — the originating device and a digest of the type-specific
// comparison content — into crdt_op_identities. Untrimmed ids keep answering
// from their merge row, so the table holds one small fixed-size record per
// trimmed id, never one per accepted operation.
//
// The table never participates in a merge: the counter sum, the set union,
// the register winner and the live orset tags are all derived without it.

package crdt

import (
	"bytes"
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"errors"
	"sort"
)

// canonicalDigest renders the type-specific comparison content of op in a
// single canonical form and hashes it, prefixed by the type so contents of
// different types never collide. Two submissions of one id carry the same
// digest exactly when the submission layer's existing equality rules accept
// the second as idempotent:
//
//   - counter: the decoded non-negative integer (client formatting ignored);
//   - gset: the element set (order and duplicates ignored), rendered as a
//     sorted unique JSON array;
//   - register: the version together with the JSON-semantic value (1 and 1.0
//     and reordered object keys compare equal);
//   - orset: the action and the element.
func canonicalDigest(docType string, op Op) ([]byte, error) {
	var content []byte
	switch docType {
	case TypeCounter:
		n, err := decodeCounterValue(op.Value)
		if err != nil {
			return nil, err
		}
		raw, err := json.Marshal(n)
		if err != nil {
			return nil, err
		}
		content = raw
	case TypeGSet:
		set := make(map[string]struct{}, len(op.Elements))
		for _, element := range op.Elements {
			set[element] = struct{}{}
		}
		elements := make([]string, 0, len(set))
		for element := range set {
			elements = append(elements, element)
		}
		sort.Strings(elements)
		raw, err := json.Marshal(elements)
		if err != nil {
			return nil, err
		}
		content = raw
	case TypeRegister:
		if op.Version < 0 {
			return nil, errors.New("register version must be a non-negative integer")
		}
		var value any
		if err := json.Unmarshal(op.Value, &value); err != nil {
			return nil, err
		}
		// Re-marshaling the decoded value canonicalizes whitespace and object
		// key order exactly the way JSONEqual compares values; wrapping it in
		// a fixed-field struct folds the version into the same canonical bytes.
		valueBytes, err := json.Marshal(value)
		if err != nil {
			return nil, err
		}
		raw, err := json.Marshal(struct {
			Version int64           `json:"version"`
			Value   json.RawMessage `json:"value"`
		}{Version: op.Version, Value: json.RawMessage(valueBytes)})
		if err != nil {
			return nil, err
		}
		content = raw
	case TypeORSet:
		if op.Action != ORSetAdd && op.Action != ORSetRemove {
			return nil, errors.New(`orset action must be "add" or "remove"`)
		}
		content = []byte(encodeORSetContent(op.Action, op.Element))
	default:
		return nil, errors.New("unknown crdt type")
	}

	h := sha256.New()
	_, _ = h.Write([]byte(docType))
	_, _ = h.Write([]byte{0})
	_, _ = h.Write(content)
	return h.Sum(nil), nil
}

// resolveTrimmedIdentity answers the submission question for an id whose
// merge row is absent because compaction trimmed it. It returns true when the
// retained identity matches op's originating device and comparison content
// (an idempotent replay), an *ErrConflict when a retained identity exists but
// differs, and false with no error when no identity was retained (a genuinely
// new id, which proceeds through the normal acceptance path).
func resolveTrimmedIdentity(tx *sql.Tx, documentID, docType, mismatchReason string, op Op) (bool, error) {
	digest, err := canonicalDigest(docType, op)
	if err != nil {
		return false, &ErrConflict{ID: op.ID, Reason: err.Error()}
	}

	var existingDevice string
	var existingDigest []byte
	err = tx.QueryRow(
		`SELECT device_id, digest FROM crdt_op_identities WHERE document_id = ? AND id = ?`,
		documentID, op.ID,
	).Scan(&existingDevice, &existingDigest)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, err
	}

	if existingDevice != op.DeviceID || !bytes.Equal(existingDigest, digest) {
		return false, &ErrConflict{ID: op.ID, Reason: mismatchReason}
	}
	return true, nil
}

// retainIdentity moves the comparable identity (device plus content digest) of
// one operation row compaction is about to drop into crdt_op_identities. A
// row is dropped at most once so the id is absent, but INSERT OR IGNORE keeps
// a repeat compaction finding the same row a harmless no-op.
func retainIdentity(tx *sql.Tx, documentID, docType string, op Op) error {
	digest, err := canonicalDigest(docType, op)
	if err != nil {
		return err
	}
	_, err = tx.Exec(
		`INSERT OR IGNORE INTO crdt_op_identities (document_id, id, device_id, digest) VALUES (?, ?, ?, ?)`,
		documentID, op.ID, op.DeviceID, digest,
	)
	return err
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"time"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// subscribePageLimit is the page size used while replaying changes already
// committed after the subscription cursor. It matches the largest page the
// paginated read endpoint accepts, so catch-up and reads stay page-aligned.
const subscribePageLimit = 1000

// wsCloseEchoWait bounds how long a server-initiated close waits for the
// client's close echo before the deferred TCP teardown.
const wsCloseEchoWait = 500 * time.Millisecond

// handleSubscribe is the WebSocket document subscription mounted under the
// session view:
//
//	GET /v1/sessions/{sessionId}/documents/{documentId}/changes/subscribe?cursor=N
//
// The subscription identity is entirely the existing session: the session's
// owning device is the only credential. Validation happens entirely before
// the 101 handshake and writes nothing:
//
//  1. cursor must be a non-negative decimal integer (400 JSON otherwise),
//  2. the request must carry a valid WebSocket upgrade handshake (400 JSON),
//  3. the session must currently exist (404 JSON),
//  4. its device must currently hold permission for the document (403 JSON).
//
// After the upgrade the server first sends every committed change with a
// cursor greater than the starting cursor — paged in cursor order, one text
// frame per record in the exact {"id","deviceId","payload","cursor"} shape of
// a paginated read row — then seamlessly continues with changes committed by
// any write path (batch post, merge, restore, replay). Frames are never
// reordered or coalesced; a later read from the last observed cursor returns
// the same rows. The connection is push-only: inbound data frames are read
// and discarded, only close/ping control frames are honored.
//
// A permission revoked after the upgrade ends the subscription with close
// code 4403 and no further frame follows; a termination signal ends every
// subscription with 1001. A client disconnect simply unregisters — like long
// polling, a subscription writes no change, cursor or other record.
func handleSubscribe(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// Parameter shape first: a bad cursor is a 400 even when the session or
	// handshake is also bad, matching the session-scoped read ordering.
	cursor, ok := parseSubscribeCursor(w, r)
	if !ok {
		return
	}
	if !checkWebSocketUpgrade(r) {
		writeError(w, http.StatusBadRequest, "a WebSocket upgrade handshake is required")
		return
	}

	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}
	authorized, err := s.DocumentAuthorized(documentID, deviceID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to look up permission")
		return
	}
	if !authorized {
		writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		return
	}

	conn, err := upgradeWebSocket(w, r)
	if err != nil {
		// The 101 response could not be written and the connection has been
		// hijacked (or is gone), so no JSON error can be produced. Nothing
		// was registered or written to the store.
		return
	}

	serveSubscription(r, s, conn, documentID, deviceID, cursor)
}

// parseSubscribeCursor validates the mandatory cursor query parameter: it
// must be present and a decimal non-negative integer. Negative, fractional
// and non-numeric values are a 400 JSON error; signs and adornments are
// rejected.
func parseSubscribeCursor(w http.ResponseWriter, r *http.Request) (int64, bool) {
	raw := r.URL.Query().Get("cursor")
	// parseCursorPath accepts only decimal digits (no sign, fraction or
	// exponent); a missing parameter is an empty raw and is rejected too.
	cursor, ok := parseCursorPath(raw)
	if !ok {
		writeError(w, http.StatusBadRequest, "cursor must be a non-negative integer")
		return 0, false
	}
	return cursor, true
}

// serveSubscription runs one upgraded connection to completion. It registers
// before the first log read (a commit landing during catch-up is therefore
// never missed), then alternates a flush phase — drain every page of changes
// past the last sent cursor — and a park phase on the wake channel. A revoke
// is acted on only after the committed tail is flushed, so a commit that was
// authorized when it landed is still delivered ahead of the 4403. The method
// returns when the client leaves, permission is revoked or the store starts
// closing; the hijacked connection is closed on exit.
func serveSubscription(r *http.Request, s *app.App, conn *wsConn, documentID, deviceID string, cursor int64) {
	// Registration precedes the first read: the wake channel is buffered, so
	// a commit during a read leaves a pending wake that makes the next park
	// return immediately — no wake is lost. The revoked channel closes once
	// if access is withdrawn, and that event survives a racing re-grant.
	wakeCh, revokedCh, unregister := s.AddSubscription(documentID, deviceID)
	defer func() {
		unregister()
		_ = conn.NetClose()
	}()

	clientGone := make(chan struct{})
	go func() {
		defer close(clientGone)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				// A malformed frame ends the connection with the RFC
				// protocol-error code; a client close is already echoed
				// inside ReadMessage; a network drop needs no frame.
				var protoErr *wsProtocolErrorString
				if errors.As(err, &protoErr) {
					_ = conn.Close(wsCloseProtocolError, "protocol error")
				}
				return
			}
			// Push-only channel: an inbound data frame is read and
			// discarded; the client cannot mutate the log over it.
		}
	}()

	// checkEnd non-blockingly maps a closing store to 1001 and a sticky
	// revoke to 4403; it returns true when the subscription must end. A
	// termination signal takes precedence: SIGTERM must end every
	// subscription with 1001 even if a revoke is also pending.
	checkEnd := func() bool {
		if s.Closing() {
			endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
			return true
		}
		select {
		case <-revokedCh:
			endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
			return true
		default:
		}
		return false
	}

	position := cursor
	first := true
	for {
		if !first {
			// Park until a commit, a sticky revoke or the termination signal
			// wakes us. r.Context() covers a non-shutdown cancel; the read
			// pump covers a client disconnect.
			select {
			case <-wakeCh:
				// Drain any coalesced follow-up signal as well; the flush
				// below reconciles every case by re-reading from the last
				// sent cursor.
				select {
				case <-wakeCh:
				default:
				}
			case <-revokedCh:
				if s.Closing() {
					endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
					return
				}
				endSubscription(conn, clientGone, wsClosePermissionRevoked, "permission revoked")
				return
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			}
			if s.Closing() {
				endSubscription(conn, clientGone, wsCloseGoingAway, "going away")
				return
			}
		}
		first = false

		// Flush phase: page every change past position in cursor order. A
		// termination signal or a revoke is honored between pages/rows so a
		// large catch-up cannot delay the closing frame. A revoke arriving
		// while the final already-authorized tail is in flight is checked
		// after the inner loop, so that tail still goes out first.
		for {
			if checkEnd() {
				return
			}
			select {
			case <-clientGone:
				return
			case <-r.Context().Done():
				return
			default:
			}

			changes, _, err := s.ListChanges(documentID, position, subscribePageLimit)
			if err != nil {
				_ = conn.Close(wsCloseInternalError, "internal error")
				return
			}
			for i := range changes {
				if checkEnd() {
					return
				}
				raw, marshalErr := json.Marshal(changes[i])
				if marshalErr != nil {
					_ = conn.Close(wsCloseInternalError, "internal error")
					return
				}
				if writeErr := conn.WriteText(raw); writeErr != nil {
					return
				}
				position = changes[i].Cursor
			}
			if len(changes) < subscribePageLimit {
				break
			}
		}

		// Caught up. A revoke that arrived during the last page (its tail was
		// just flushed) now ends the subscription; otherwise loop and park.
		// Closing still wins over a pending revoke.
		if checkEnd() {
			return
		}
	}
}

// endSubscription sends the mandated closing frame and briefly waits for the
// read pump to observe the peer's close echo, so a graceful close reaches the
// client instead of being truncated by the deferred TCP teardown. It returns
// promptly if the peer is already gone; the caller's deferred NetClose drops
// the socket either way.
func endSubscription(conn *wsConn, clientGone <-chan struct{}, code int, reason string) {
	_ = conn.Close(code, reason)
	timer := time.NewTimer(wsCloseEchoWait)
	defer timer.Stop()
	select {
	case <-clientGone:
	case <-timer.C:
	}
}

package server

import (
	"encoding/json"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// snapshotExportItem is one element of an export body. The struct field order
// fixes the on-the-wire key order to cursor then state; State is embedded as
// raw JSON so the stored content is emitted verbatim, exactly as the single
// snapshot read emits it.
type snapshotExportItem struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// snapshotExportResponse is the export body with the top-level key order fixed
// to snapshots then count. Snapshots is always a non-nil slice so an empty
// export serializes as [] rather than null.
type snapshotExportResponse struct {
	Snapshots []snapshotExportItem `json:"snapshots"`
	Count     int                  `json:"count"`
}

// handleExportSnapshots is the read-only batch export over a document's
// snapshot collection:
//
//	GET /v1/documents/{documentID}/snapshots?from=0&to=N
//
// from defaults to 0; to absent means no upper bound. Only snapshots whose
// cursor is in the closed [from, to] interval are returned, in ascending
// cursor order, at most one entry per cursor. An unknown document or a range
// without any snapshot is a successful 200 with an empty list and count 0, not
// an error. The handler writes nothing: it creates no snapshot, moves no
// cursor, records no change and notifies the push channels.
func handleExportSnapshots(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	q := r.URL.Query()

	from := int64(0)
	if raw := q.Get("from"); raw != "" {
		v, ok := parseCursorPath(raw)
		if !ok {
			writeError(w, http.StatusBadRequest, "from must be a non-negative integer")
			return
		}
		from = v
	}

	var to *int64
	if raw := q.Get("to"); raw != "" {
		v, ok := parseCursorPath(raw)
		if !ok {
			writeError(w, http.StatusBadRequest, "to must be a non-negative integer")
			return
		}
		to = &v
	}
	if to != nil && *to < from {
		writeError(w, http.StatusBadRequest, "to must not be less than from")
		return
	}

	snaps, err := s.ExportSnapshots(documentID, from, to)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to export snapshots")
		return
	}

	items := make([]snapshotExportItem, 0, len(snaps))
	for _, snap := range snaps {
		items = append(items, snapshotExportItem{Cursor: snap.Cursor, State: snap.State})
	}
	writeJSON(w, http.StatusOK, snapshotExportResponse{Snapshots: items, Count: len(items)})
}

// malformedSnapshotPath reports whether p targets the snapshot namespace but
// is not at one of its two exact locations:
//
//	GET  /v1/documents/{documentID}/snapshots          (the batch export)
//	GET  /v1/documents/{documentID}/snapshots/{cursor} (the single read)
//
// A trailing slash (an empty cursor segment, including the collection path
// with a trailing slash), extra path segments, or a "snapshots" segment in any
// keyword position short of one of those shapes is a malformed 400 rather than
// ServeMux's redirect or plain-text 404/405: the snapshot endpoints promise a
// JSON error and never a redirect. Empty segments are already rejected by the
// guard itself. The keyword is matched only past the documentID position, so a
// document literally named "snapshots" keeps its ordinary routes.
func malformedSnapshotPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	for i, seg := range segs {
		if seg != "snapshots" || i == 0 {
			continue
		}
		// Keyword position reached. The collection is exactly
		// {documentID}/snapshots; the single read adds one non-empty cursor
		// segment. Anything else (trailing slash, missing/extra segments) is
		// malformed.
		collection := len(segs) == 2 && segs[0] != ""
		item := len(segs) == 3 && segs[0] != "" && segs[2] != ""
		return !(collection || item)
	}
	return false
}

// Package store is the durable kernel shared by the internal services: it
// owns the SQLite database handle and the registration layer (devices and
// sessions) plus resumable attachments.
//
// The business services layered on top of the kernel — the change event log,
// the permission ledger and the CRDT state — live in their own packages and
// cooperate only through their internal interfaces. They all share this one
// handle: it opens a single pooled connection with immediate write
// transactions, so every service's transactional judgment is serialized on
// the same connection and no batch is ever half written.
//
// Devices and sessions form the registration layer. A device registers with a
// client-supplied id; a session belongs to exactly one registered device and
// is addressed by its own client-supplied id. Registration and session
// creation are idempotent re-posts: the first call creates, an identical
// repeat does not. A session id already owned by another device is a
// conflict, never silently re-homed. Deletes are owner-scoped and hard: a
// repeat delete, another device, and a cross-device path all miss with 404,
// after which the id is free to be created again. A device itself can
// deregister: the device row and everything it owns — its sessions and the
// attachments it created, chunks and grants included — vanish in one
// serialized transaction, a repeat or never-registered deregistration misses
// with 404 and writes nothing, and the freed id registers again as a
// brand-new device.
//
// Attachments are resumable chunked uploads owned by the registered device
// that created them. Creation pins the declared total size, chunk size and
// SHA-256 digest; chunks land in any order and are stored durably as they
// arrive, so an interrupted upload resumes after a restart with its
// idempotency and conflict decisions intact. Finishing concatenates the
// chunks, verifies the digest and seals the upload; a sealed upload is
// immutable and rejects every further chunk write. Finished content is
// addressed by digest, so a second attachment with the same digest and size
// reuses the stored bytes instead of copying them. The creator may grant
// other registered devices read-only access per attachment; every
// (attachment, device) pair starts unauthorized, grants and revokes commit in
// the same serialized way, and access never widens the write paths. Deletes
// are owner-scoped and hard: the record, its chunks and its grants vanish in
// one serialized transaction, a repeat delete misses with 404, the id is free
// to be created again, and the shared content bytes are reclaimed once the
// last completed attachment referencing them is gone.
package store

import (
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// ErrDeviceNotFound reports that an operation targets a device id that was
// never registered. Services map it to 404; nothing is written.
var ErrDeviceNotFound = errors.New("device not found")

// ErrPermissionDenied reports that a device's access to a document has been
// revoked. Services map it to 403; nothing is written and no document content
// is exposed. It is a shared verdict produced by the permission service and
// consulted by every service that enforces the gate inside a transaction.
var ErrPermissionDenied = errors.New("device permission for this document has been revoked")

// ErrSessionConflict reports that a session id already belongs to a different
// device. The session keeps its original owner; nothing is written. Services
// map it to 409.
type ErrSessionConflict struct {
	ID string
}

func (e *ErrSessionConflict) Error() string {
	return fmt.Sprintf("session %q belongs to another device", e.ID)
}

// ErrSessionNotFound reports that no live session matches the (device,
// session) pair: the session was never created, was already deleted, or
// belongs to another device. Services map it to 404.
var ErrSessionNotFound = errors.New("session not found")

// DBTX is the subset of *sql.DB and *sql.Tx the services use for their
// serialized work, so judgments made "in the same transaction" (for example a
// permission gate followed by the gated write) run on one concrete connection
// whether the caller holds a transaction or the handle itself.
type DBTX interface {
	Exec(query string, args ...any) (sql.Result, error)
	Query(query string, args ...any) (*sql.Rows, error)
	QueryRow(query string, args ...any) *sql.Row
}

// Store is the durable kernel: one SQLite database handle together with the
// device, session and attachment data it owns.
type Store struct {
	db *sql.DB
}

// Open opens (creating if needed) the SQLite database at path. The empty path
// opens an in-memory database useful for tests.
func Open(path string) (*Store, error) {
	if path == "" {
		// With a single pooled connection this is a private, per-instance
		// in-memory database (useful for tests).
		path = "file::memory:"
	}
	// _txlock=immediate makes writers acquire the write lock at BEGIN, so
	// concurrent batches serialize without SQLITE_BUSY deadlocks.
	dsn := path + "?_txlock=immediate&_busy_timeout=5000&_journal_mode=WAL&_synchronous=FULL&_foreign_keys=on"
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// One connection avoids cross-connection locking surprises; writes are
	// serialized by the immediate transaction anyway, and SQLite concurrency
	// for readers does not help correctness here. It also keeps every
	// service's transaction serialized on the same connection.
	db.SetMaxOpenConns(1)
	s := &Store{db: db}
	if err := s.init(); err != nil {
		_ = db.Close()
		return nil, err
	}
	return s, nil
}

// DB returns the underlying handle. The business services use it to open the
// serialized transactions their judgments run in; callers outside the
// internal packages never need it.
func (s *Store) DB() *sql.DB { return s.db }

// Close releases the database handle.
func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) init() error {
	_, err := s.db.Exec(`
CREATE TABLE IF NOT EXISTS devices (
	id TEXT NOT NULL PRIMARY KEY
);
CREATE TABLE IF NOT EXISTS sessions (
	id        TEXT NOT NULL PRIMARY KEY,
	device_id TEXT NOT NULL REFERENCES devices(id)
);
CREATE INDEX IF NOT EXISTS sessions_device_idx
	ON sessions(device_id);
CREATE TABLE IF NOT EXISTS attachments (
	id          TEXT NOT NULL PRIMARY KEY,
	device_id   TEXT NOT NULL REFERENCES devices(id),
	total_bytes INTEGER NOT NULL,
	chunk_size  INTEGER NOT NULL,
	sha256      TEXT NOT NULL,
	complete    INTEGER NOT NULL DEFAULT 0,
	reused      INTEGER NOT NULL DEFAULT 0,
	created_seq INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS attachment_chunks (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	idx           INTEGER NOT NULL,
	data          BLOB NOT NULL,
	PRIMARY KEY (attachment_id, idx)
);
CREATE TABLE IF NOT EXISTS attachment_contents (
	sha256 TEXT NOT NULL PRIMARY KEY,
	size   INTEGER NOT NULL,
	data   BLOB NOT NULL
);
CREATE TABLE IF NOT EXISTS attachment_access (
	attachment_id TEXT NOT NULL REFERENCES attachments(id),
	device_id     TEXT NOT NULL,
	authorized    INTEGER NOT NULL,
	granted_seq   INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY (attachment_id, device_id)
);
`)
	if err != nil {
		return err
	}
	if err := s.ensureAttachmentCreatedSeq(); err != nil {
		return err
	}
	return s.ensureAttachmentAccessGrantedSeq()
}

// ensureAttachmentCreatedSeq adds the creation-order column to databases
// created before it existed. Existing rows are backfilled in insertion
// (rowid) order so their relative listing order is unchanged; new rows take
// strictly larger values, so the sequence never reuses a value even after
// the newest attachment is deleted and its id created again.
func (s *Store) ensureAttachmentCreatedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachments)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "created_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachments ADD COLUMN created_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachments SET created_seq = (
			SELECT COUNT(*) FROM attachments older WHERE older.rowid <= attachments.rowid
		)`,
	)
	return err
}

// ensureAttachmentAccessGrantedSeq adds the grant-order column to access
// tables created before it existed. Existing rows are backfilled one past the
// per-attachment maximum in insertion (rowid) order, so surviving grants keep
// a stable relative order; every new grant takes a strictly larger value, even
// after the previously newest grant was revoked, so a re-granted device lists
// at the position of its latest grant and a value is never reused.
func (s *Store) ensureAttachmentAccessGrantedSeq() error {
	rows, err := s.db.Query(`PRAGMA table_info(attachment_access)`)
	if err != nil {
		return err
	}
	hasColumn := false
	for rows.Next() {
		var cid, notNull, pk int
		var name, colType string
		var dflt sql.NullString
		if err := rows.Scan(&cid, &name, &colType, &notNull, &dflt, &pk); err != nil {
			_ = rows.Close()
			return err
		}
		if name == "granted_seq" {
			hasColumn = true
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	_ = rows.Close()
	if hasColumn {
		return nil
	}
	if _, err := s.db.Exec(
		`ALTER TABLE attachment_access ADD COLUMN granted_seq INTEGER NOT NULL DEFAULT 0`,
	); err != nil {
		return err
	}
	_, err = s.db.Exec(
		`UPDATE attachment_access SET granted_seq = (
			SELECT rn FROM (
				SELECT rowid AS rid,
				       ROW_NUMBER() OVER (PARTITION BY attachment_id ORDER BY rowid) AS rn
				FROM attachment_access
			) WHERE rid = attachment_access.rowid
		)`,
	)
	return err
}

// RegisterDevice registers a device by client-supplied id. The first call for
// an id creates it and reports created=true; repeating the registration is
// idempotent (created=false). Device identity never changes.
func (s *Store) RegisterDevice(deviceID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	created, err = RegisterDeviceTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	return created, tx.Commit()
}

// RegisterDeviceTx is RegisterDevice against an existing transaction, so the
// services can resolve the registration layer as the first step of a larger
// serialized transaction (their permission/content gates then share it).
func RegisterDeviceTx(q DBTX, deviceID string) (created bool, err error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	if !exists {
		if _, err := q.Exec(`INSERT INTO devices (id) VALUES (?)`, deviceID); err != nil {
			return false, err
		}
		return true, nil
	}
	return false, nil
}

// DeviceExistsTx reports whether deviceID is registered, evaluated inside q so
// a service's gate runs on the same transaction as the work it guards.
func DeviceExistsTx(q DBTX, deviceID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// CreateSession creates a session owned by deviceID with a client-supplied id.
//
//   - An unknown device yields ErrDeviceNotFound; nothing is written.
//   - A session id already owned by another device yields *ErrSessionConflict;
//     nothing is written and the owner is unchanged.
//   - Re-posting the same (device, session) pair is idempotent: created=false.
//
// A deleted session is gone for good, so its id can be registered again as a
// brand-new session (created=true). The lookup, owner check and insert run in
// one serialized transaction, so concurrent creates of the same session id
// cannot both create it.
func (s *Store) CreateSession(deviceID, sessionID string) (created bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	var deviceExists bool
	if err := tx.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM devices WHERE id = ?)`, deviceID,
	).Scan(&deviceExists); err != nil {
		return false, err
	}
	if !deviceExists {
		return false, ErrDeviceNotFound
	}

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO sessions (id, device_id) VALUES (?, ?)`,
			sessionID, deviceID,
		); err != nil {
			return false, err
		}
		if err := tx.Commit(); err != nil {
			return false, err
		}
		return true, nil
	case err != nil:
		return false, err
	}

	if owner != deviceID {
		return false, &ErrSessionConflict{ID: sessionID}
	}
	return false, tx.Commit()
}

// DeleteSession removes the live session matching the (deviceID, sessionID)
// pair. Any miss — the session does not exist, was already deleted, or belongs
// to another device — returns ErrSessionNotFound and changes nothing. The
// check and the delete run in one transaction, so a concurrent create cannot
// interleave and a repeat delete still misses; the removal is committed to
// disk before the call returns.
func (s *Store) DeleteSession(deviceID, sessionID string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	var owner string
	err = tx.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&owner)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrSessionNotFound
	case err != nil:
		return err
	}
	if owner != deviceID {
		return ErrSessionNotFound
	}

	if _, err := tx.Exec(
		`DELETE FROM sessions WHERE id = ? AND device_id = ?`,
		sessionID, deviceID,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// DeleteDeviceTx deregisters deviceID and removes every record it owns, all
// inside the caller's serialized transaction:
//
//   - the device's sessions are hard-deleted, so their session-scoped reads
//     and subscriptions miss from then on;
//   - every attachment it created is removed together with its chunks, its
//     sealed/unfinished state and the access rows other devices held on it;
//   - the read grants the device itself held on other devices' attachments
//     are withdrawn;
//   - the device row is removed last (every child row goes first).
//
// Digest-addressed content is shared across attachments and is reclaimed only
// when no completed attachment still references a digest — exactly the rule
// of a single attachment delete — so another device's attachment with the same
// digest keeps its bytes and one deregistration by itself never reclaims
// shared content. The document permission ledger lives in the authz package
// and clears its own rows against the same transaction through
// DeleteDevicePermissionsTx.
//
// An unknown (never registered or already deregistered) device yields
// ErrDeviceNotFound and writes nothing. Because the whole judgment runs in one
// immediate transaction on the single shared connection, concurrent
// deregistrations of the same device commit at most once and any concurrent
// chunk upload or finish either committed entirely before it or is rejected
// entirely afterward — no half-written record survives.
func DeleteDeviceTx(q DBTX, deviceID string) error {
	exists, err := DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return ErrDeviceNotFound
	}

	// Remember the digests of the device's completed attachments before their
	// rows vanish: each is a candidate for content reclamation once every
	// owned attachment is gone. DISTINCT because several of the device's
	// attachments may share the same digest-addressed content.
	rows, err := q.Query(
		`SELECT DISTINCT sha256 FROM attachments WHERE device_id = ? AND complete = 1`,
		deviceID,
	)
	if err != nil {
		return err
	}
	var digests []string
	for rows.Next() {
		var digest string
		if err := rows.Scan(&digest); err != nil {
			_ = rows.Close()
			return err
		}
		digests = append(digests, digest)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	// Withdraw the read grants this device held on other devices'
	// attachments (rows naming it as the grantee), then remove the access
	// rosters of the attachments it created before the attachment rows those
	// rosters reference are deleted.
	if _, err := q.Exec(
		`DELETE FROM attachment_access WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_access
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachment_chunks
		 WHERE attachment_id IN (SELECT id FROM attachments WHERE device_id = ?)`,
		deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM attachments WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}

	// Reclaim each digest-addressed content only when no surviving completed
	// attachment — owned by another device, or by the deregistered device in
	// an impossible re-read — still references it.
	for _, digest := range digests {
		var stillReferenced bool
		if err := q.QueryRow(
			`SELECT EXISTS(SELECT 1 FROM attachments WHERE sha256 = ? AND complete = 1)`,
			digest,
		).Scan(&stillReferenced); err != nil {
			return err
		}
		if !stillReferenced {
			if _, err := q.Exec(
				`DELETE FROM attachment_contents WHERE sha256 = ?`, digest,
			); err != nil {
				return err
			}
		}
	}

	if _, err := q.Exec(
		`DELETE FROM sessions WHERE device_id = ?`, deviceID,
	); err != nil {
		return err
	}
	if _, err := q.Exec(
		`DELETE FROM devices WHERE id = ?`, deviceID,
	); err != nil {
		return err
	}
	return nil
}

// SessionExists reports whether a live session with sessionID exists.
// Ownership is intentionally not part of this check: session-scoped reads only
// require that the session currently exists.
func (s *Store) SessionExists(sessionID string) (bool, error) {
	var exists bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM sessions WHERE id = ?)`, sessionID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// SessionDevice returns the id of the device that owns the live session
// sessionID. A session that was never created or was deleted yields
// ErrSessionNotFound.
func (s *Store) SessionDevice(sessionID string) (string, error) {
	var deviceID string
	err := s.db.QueryRow(
		`SELECT device_id FROM sessions WHERE id = ?`, sessionID,
	).Scan(&deviceID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return "", ErrSessionNotFound
	case err != nil:
		return "", err
	default:
		return deviceID, nil
	}
}

// JSONEqual reports whether two payloads are equal after JSON decoding, so
// 1 and 1.0, or {"a":1,"b":2} and {"b":2,"a":1}, compare equal. It is shared
// verbatim by the change event and CRDT services' idempotency judgments.
func JSONEqual(a, b json.RawMessage) bool {
	var va, vb any
	if err := json.Unmarshal(a, &va); err != nil {
		return false
	}
	if err := json.Unmarshal(b, &vb); err != nil {
		return false
	}
	return deepEqual(va, vb)
}

func deepEqual(a, b any) bool {
	switch av := a.(type) {
	case nil:
		return b == nil
	case bool:
		bv, ok := b.(bool)
		return ok && av == bv
	case string:
		bv, ok := b.(string)
		return ok && av == bv
	case float64:
		bv, ok := b.(float64)
		return ok && av == bv
	case []any:
		bv, ok := b.([]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for i := range av {
			if !deepEqual(av[i], bv[i]) {
				return false
			}
		}
		return true
	case map[string]any:
		bv, ok := b.(map[string]any)
		if !ok || len(av) != len(bv) {
			return false
		}
		for k, v := range av {
			w, exists := bv[k]
			if !exists || !deepEqual(v, w) {
				return false
			}
		}
		return true
	default:
		return false
	}
}

