			documentID, t.id, t.deviceID,
			changeDigest(t.payload, t.restoredFrom), t.cursor,
		); err != nil {
			return CompactResult{}, err
		}
	}

	res, err := tx.Exec(
		`DELETE FROM changes WHERE document_id = ? AND cursor <= ?`,
		documentID, boundary,
	)
	if err != nil {
		return CompactResult{}, err
	}
	removed, err := res.RowsAffected()
	if err != nil {
		return CompactResult{}, err
	}
