	if err != nil {
		t.Fatal(err)
	}
	if restored.Cursor != 3 {
		t.Fatalf("restore cursor = %d, want 3", restored.Cursor)
	}
	if _, err := s.PutSnapshot("doc", 3, json.RawMessage(`{"s":2}`)); err != nil {
		t.Fatal(err)
	}
	res, err := s.CompactChanges("doc", "dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if res.Boundary != 3 || res.Removed != 3 {
