	again, err := s.RestoreSnapshot("doc", "dev-1", "restore-1", 1)
	if err != nil {
		t.Fatal(err)
	}
	if again.Created || again.Cursor != 3 || again.RestoredFrom != 1 {
		t.Fatalf("re-restore = %+v, want created=false cursor 3 from 1", again)
	}
