	for i := 0; i < n; i++ {
		batch[i] = events.Change{ID: ids[i], DeviceID: "dev-1", Payload: json.RawMessage(`{"n":` + jsonNumber(i+1) + `}`)}
	}
	if _, err := s.PostChanges(doc, batch); err != nil {
		t.Fatal(err)
	}
